-- Attestation style calibration 2026-10-20: 7 additional original REVIEW pedagogy candidates.
-- Style inspiration only from Drive 2024/25/26 historic pedagogy collections; authoritative content = canonical M14-M16 + official 2026 exam specification.
-- Idempotent source-reference guard. No learner publication, previous question mutation, or invented editorial attestations.
BEGIN;
DO $calibrate$
DECLARE v jsonb; v_q uuid; v_o uuid; v_ids uuid[]; v_payload jsonb; v_pairs jsonb; v_subject uuid; v_construct uuid; v_lesson uuid; v_group text; v_ref text; v_type text; i integer; j integer;
BEGIN
 SELECT id INTO STRICT v_subject FROM public.subjects WHERE code='informatika';
 FOR v IN SELECT value FROM jsonb_array_elements($bank$[{"c":"KS.02","type":"Y1","k":"mulohaza","d":4,"s":"Loyiha darsida guruhlar chiroyli taqdimot tayyorladi. Ammo kuzatuv varag‘iga ko‘ra, taqdimotning deyarli barchasini ikki o‘quvchi bajargan, qolganlar esa mavzu bo‘yicha savolga javob bera olmadi. Dars samaradorligini oshirish uchun qaysi o‘zgarish eng asosli?","o":["Guruh mahsulotini yagona baholab, keyingi darsda ham o‘sha rollarni saqlash","Har bir o‘quvchining aniq roli, hissasi va individual natijasini tekshirish","Guruh taqdimotiga ko‘proq vaqt ajratib, faollikni faqat kuzatish orqali aniqlash","Taqdimot dizaynini baholashga urg‘u berib, mavzuni yana umumiy tushuntirish"],"a":1,"e":"Guruhli faoliyatning samarasi har bir o‘quvchining maqsadga mos ishtiroki va o‘zlashtirish darajasi bilan o‘lchanadi."},{"c":"KS.04","type":"Y1","k":"qollash","d":3,"s":"Sinfning ekologik loyihasida ikki guruh vazifalarni bo‘lishishda kelisha olmadi. Sinf rahbari ularga o‘zaro tinglash qoidalarini muhokama qildirdi, vazifalarni qayta taqsimladi va loyiha oxirida hamkorlikni birgalikda baholashni taklif etdi. Qaysi tarbiyaviy natija markazga qo‘yilgan?","o":["Faqat ekologik mavzuning nazariy atamalarini eslab qolish darajasini oshirish","Mas’uliyat, kelishuv va jamoaviy qaror ko‘nikmalarini faoliyatda mustahkamlash","Tadbir mahsulotini mezonsiz tanlash va loyiha bosqichlarini tezroq yakunlash","Sinfdagi faollikni faqat intizom qaydlari va tashqi rag‘bat bilan o‘lchash"],"a":1,"e":"Tarbiyaviy faoliyat hurmat, mas’uliyat va hamkorlikni real munosabatlarda mustahkamlaydi."},{"c":"KS.06","type":"Y1","k":"mulohaza","d":4,"s":"O‘qituvchi hamkasbining darsini kuzatib, mustaqil ishlash vaqtini aniq chegaralash usulini o‘rgandi. O‘z sinfida sinab ko‘rganida ayrim o‘quvchilar topshiriqni tezroq tugatdi, biroq qolganlarda xatolar ko‘paydi. Kasbiy o‘sish siklini davom ettirish uchun eng ma’qul ish qaysi?","o":["Usul hamkasbda ishlagani uchun keyingi darslarda aynan shu tartibni hech qanday o‘zgarishsiz saqlab qolish","Natijalarni guruhlar bo‘yicha tahlil qilib, vaqt va yordamni dalil asosida moslashtirish","Faqat tez bajarganlarning fikrini yozib, qolgan natijalarni keyingi chorakka qoldirish","Avvalgi metodga darhol qaytib, sinov kuzatuvlarini kasbiy portfelga kiritmaslik"],"a":1,"e":"Refleksiya o‘z usulingizni kuzatuv dalili bilan baholash va keyingi sinovga moslashtirishni talab etadi."},{"c":"KS.07","type":"Y1","k":"mulohaza","d":4,"s":"O‘quvchining davomatida va topshiriqlarni bajarishida o‘zgarish kuzatildi. Fan o‘qituvchisi ota-ona va sinf rahbari bilan muhokama o‘tkazmoqchi, lekin suhbatda bolaning shaxsiy oilaviy holatiga oid ma’lumot ham bor. Qaysi hamkorlik usuli eng asosli?","o":["Barcha shaxsiy ma’lumotni umumiy ota-onalar guruhiga yuborib, jamoaviy nazoratni yanada kuchaytirish","Zarur ma’lumotni tegishli shaxslar bilan maxfiy muhokama qilib, yordam rejasini kelishish","Mavjud ma’lumotni boshqa o‘quvchilarga ham tushuntirib, o‘zaro kuzatuvni tashkil etish","Ota-ona bilan suhbatni bekor qilib, faqat baholar ro‘yxatini maktab devoriga chiqarish"],"a":1,"e":"Hamkorlik maxfiylik va o‘quvchi manfaatlarini himoya qilgan holda asoslangan yordam choralarini kelishishni anglatadi."},{"c":"PM.GEN.02","type":"Y1","k":"mulohaza","d":4,"s":"O‘qituvchi foiz mavzusining ta’rifini va formulasini ko‘rsatdi, so‘ng do‘kondagi chegirma haqidagi masalani ishlatdi. Biroq o‘quvchilar javobni topgach ham vaziyatni izohlab bera olmadi. Nazariya va amaliyot birligi tamoyilini chuqurroq amalga oshirish uchun nima yetishmayapti?","o":["Formulani yoddan qayta ayttirib, narxlar haqidagi masalani keyingi yilga qoldirish","Natija ma’nosini real vaziyatda tushuntirish va hisoblash usulini asoslatish","Namoyish slaydlarini ko‘paytirib, hisoblash natijasini o‘qituvchining o‘zi berish","Chegirma tushunchasini e’tibordan chetda qoldirib, topshiriq sonini oshirish"],"a":1,"e":"Nazariya-amaliyot birligi hisoblashni real sharoitga mazmunli qo‘llash va natijani tushuntirishni talab etadi."},{"c":"PM.GEN.03","type":"Y1","k":"qollash","d":3,"s":"Maktabda o‘quvchilar mahalla daraxtlari holatini o‘rganib, chiqindilar haqida axborot varaqasi tayyorladi va tozalash tadbirida qatnashdi. Rahbar loyiha yakunida ularning tabiatga mas’uliyatli munosabati qanday o‘zgarganini kuzatdi. Ushbu faoliyatning ustuvor tarbiyaviy yo‘nalishi qaysi?","o":["Ekologik tarbiya — atrof-muhitga ongli va mas’uliyatli munosabatni shakllantirish","Estetik tarbiya — asosan badiiy did va go‘zallikni his etishni rivojlantirish","Mehnat tarbiyasi — avvalo muayyan kasb operatsiyasini egallashni tekshirish","Huquqiy tarbiya — asosan huquqiy hujjat va majburiyatlarni yodlash"],"a":0,"e":"Tarbiyaning ustuvor yo‘nalishi tadbirda bajarilgan ishga emas, uning asosiy tarbiyaviy maqsadiga ko‘ra aniqlanadi."},{"c":"PM.GEN.04","type":"Y1","k":"mulohaza","d":4,"s":"O‘qituvchi bo‘lim yakunida natijalarni tekshirdi: aksariyat o‘quvchilar asosiy tushunchalarni biladi, ammo ular orasidagi bog‘lanishni tushuntirishga qiynaladi. Keyingi mashg‘ulotda bilimlarni tizimlashtirish, umumlashtirish va turli misollarni solishtirish rejalashtirilmoqda. Yetakchi maqsadga ko‘ra bu qaysi dars turiga mos?","o":["Yangi bilim berish darsi — asosiy atamalar birinchi marta tushuntiriladigan mashg‘ulot","Umumlashtirish darsi — o‘tilgan bilimlar o‘rtasidagi bog‘lanishlar ochiladigan mashg‘ulot","Kirish darsi — bo‘limning maqsadi va dastlabki savollariga e’tibor beriladigan mashg‘ulot","Amaliy ko‘nikma darsi — asosan yangi operatsiya ketma-ketligi mashq qilinadigan mashg‘ulot"],"a":1,"e":"Oldingi bilimlarni tizimlashtirish va ular orasidagi bog‘lanishni topish umumlashtirish darsining maqsadidir."}]$bank$::jsonb) LOOP
   v_type:=v->>'type';
   v_ref:='authored:pedagogy-examstyle:20261020-wave2:'||(v->>'c')||':'||v_type||':01';
   IF EXISTS (SELECT 1 FROM public.questions WHERE source_reference=v_ref) THEN CONTINUE; END IF;
   SELECT id,group_code INTO STRICT v_construct,v_group FROM public.constructs WHERE code=v->>'c' AND is_active;
   SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.lesson_constructs lc ON lc.lesson_id=l.id WHERE lc.construct_id=v_construct AND l.status='published'::public.content_status ORDER BY l.created_at LIMIT 1;
   v_q:=gen_random_uuid();
   INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference)
   VALUES(v_q,v_subject,v_construct,v_group,v_type::public.question_format,(v->>'k')::public.cognitive_level,(v->>'d')::int,v->>'s','review'::public.content_status,NULL,false,v_lesson,v_ref);
   v_ids:=ARRAY[]::uuid[];
   IF v_type='Y1' THEN
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'a',i,v->'o'->>i);END LOOP;
     v_payload:=jsonb_build_object('correct_option_id',v_ids[(v->>'a')::int+1]);
   ELSIF v_type='Y2' THEN
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'a',i+1,v->'left'->>i);END LOOP;
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'b',i+1,v->'right'->>i);END LOOP;
     v_pairs:='{}'::jsonb;
     FOR i IN 0..3 LOOP j:=(v->'pairs'->>i)::int;v_pairs:=v_pairs||jsonb_build_object(v_ids[i+1]::text,v_ids[j+5]::text);END LOOP;
     v_payload:=jsonb_build_object('pairs',v_pairs);
   ELSIF v_type='Y3' THEN
     FOR i IN 0..3 LOOP v_ids:=array_append(v_ids,gen_random_uuid());END LOOP;
     FOR i IN 0..3 LOOP j:=(v->'display'->>i)::int;INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_ids[j+1],v_q,'a',i+1,v->'steps'->>j);END LOOP;
     v_payload:=jsonb_build_object('order',to_jsonb(v_ids));
   ELSE RAISE EXCEPTION 'Unknown format %',v_type;END IF;
   INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(v_q,v_payload,v->>'e');
 END LOOP;
 IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'authored:pedagogy-examstyle:20261020-wave2:%')<>7 THEN RAISE EXCEPTION 'Calibrated review batch count != 12';END IF;
 IF EXISTS (SELECT 1 FROM public.questions q LEFT JOIN public.question_keys k ON k.question_id=q.id WHERE q.source_reference LIKE 'authored:pedagogy-examstyle:20261020-wave2:%' AND (q.status<>'review' OR q.source_lesson_id IS NULL OR k.question_id IS NULL)) THEN RAISE EXCEPTION 'Calibrated review batch integrity fail';END IF;
END $calibrate$;
COMMIT;
